import {
  EPD_BUFFER_BYTES,
  EPD_HEIGHT,
  EPD_WIDTH,
  type EinkFramebuffer,
} from "./eink-canvas.ts";
import { FOX_ASSET_REGISTRY, UI_LAYOUT } from "./fox-sprites.ts";

/**
 * Generates the complete C++ PROGMEM header file consumed directly by firmware/.
 */
export function generateUiAssetsHeader(): string {
  const sections: string[] = [
    "#pragma once",
    "",
    "#include <stdint.h>",
    "#include <pgmspace.h>",
    "",
    "/**",
    " * AUTO-GENERATED BY FOXIE E-INK SIMULATOR (simulator/scripts/export-assets.ts).",
    " * Do not hand-edit pixel arrays; modify simulator/src/fox-sprites.ts and re-export.",
    " * Format: 1-bit monochrome, row-major, MSB-first (compatible with GxEPD2::drawBitmap).",
    " */",
    "",
    `constexpr uint16_t EPD_WIDTH = ${EPD_WIDTH};`,
    `constexpr uint16_t EPD_HEIGHT = ${EPD_HEIGHT};`,
    `constexpr uint32_t EPD_BUFFER_BYTES = ${EPD_BUFFER_BYTES};`,
    "",
    "// Shared layout coordinates (pixel-matched with simulator/src/screens.ts)",
    `constexpr int16_t UI_STATUS_BAR_H = ${UI_LAYOUT.STATUS_BAR_H};`,
    `constexpr int16_t UI_FOX_W = ${UI_LAYOUT.FOX_W};`,
    `constexpr int16_t UI_FOX_H = ${UI_LAYOUT.FOX_H};`,
    `constexpr int16_t UI_FOX_X = ${UI_LAYOUT.FOX_X};`,
    `constexpr int16_t UI_FOX_Y = ${UI_LAYOUT.FOX_Y};`,
    `constexpr int16_t UI_TITLE_Y = ${UI_LAYOUT.TITLE_Y};`,
    `constexpr int16_t UI_SUBTITLE_Y = ${UI_LAYOUT.SUBTITLE_Y};`,
    `constexpr int16_t UI_PROGRESS_Y = ${UI_LAYOUT.PROGRESS_Y};`,
    `constexpr int16_t UI_FOOTER_Y = ${UI_LAYOUT.FOOTER_Y};`,
    `constexpr int16_t UI_QR_X = ${UI_LAYOUT.QR_X};`,
    `constexpr int16_t UI_QR_Y = ${UI_LAYOUT.QR_Y};`,
    `constexpr int16_t UI_QR_SIZE = ${UI_LAYOUT.QR_SIZE};`,
    `constexpr int16_t UI_PEEK_X = ${UI_LAYOUT.PEEK_X};`,
    `constexpr int16_t UI_PEEK_Y = ${UI_LAYOUT.PEEK_Y};`,
    "",
  ];

  for (const entry of FOX_ASSET_REGISTRY) {
    sections.push(
      `constexpr uint16_t ${entry.symbol}_W = ${entry.bitmap.width};`,
      `constexpr uint16_t ${entry.symbol}_H = ${entry.bitmap.height};`,
      entry.bitmap.toCppProgmemArray(
        entry.symbol,
        `${entry.description} (${entry.bitmap.data.length} bytes)`,
      ),
      "",
    );
  }

  return sections.join("\n");
}

export function generateFullScreenCpp(
  fb: EinkFramebuffer,
  stateName: string,
): string {
  const safeName = stateName
    .toUpperCase()
    .replace(/[^A-Z0-9]+/g, "_")
    .replace(/^_|_$/g, "");
  return [
    "#pragma once",
    "#include <stdint.h>",
    "#include <pgmspace.h>",
    "",
    fb.toCppProgmemArray(`SCREEN_${safeName || "CUSTOM"}`),
    "",
  ].join("\n");
}
